SELECT id, product_name, brand, price, NTILE(4) OVER (PARTITION BY supplier_id ORDER BY price DESC, id) AS price_bucket, ROUND(cost / SUM(cost) OVER (PARTITION BY supplier_id, brand), 4) AS cost_share, AVG(cost) OVER (ORDER BY launch_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS cost_avg_6_prior, NTILE(3) OVER (PARTITION BY supplier_id ORDER BY stock_qty, id) AS stock_qty_bucket FROM products;
